"use strict";(globalThis.webpackChunkgrc||=[]).push([[9588],{63400(e){e.exports=JSON.parse('{"citeKey":"sun2000pdrs","slug":"sun-2000-pdrs-f00d","title":"PDRS: A Performance Data Representation System","authors":["X.-H. Sun","X. Wu"],"venue":"Lecture Notes in Computer Science, Springer","type":"Conference","entryType":"inproceedings","date":"April, 2000","year":2000,"era":"iit","month":4,"doi":"10.1007/3-540-45591-4_37","abstract":"We present the design and development of a Performance Data Representation System (PDRS) for scalable parallel computing. PDRS provides decision support that helps users find the right data to understand their programs\' performance and to select appropriate ways to display and analyze it. PDRS is an attempt to provide appropriate assistant to help programmers identifying performance bottlenecks and optimizing their programs.","hasAbstract":true,"lede":"We present the design and development of a Performance Data Representation System (PDRS) for scalable parallel computing.","links":{"pdf":"https://grc.iit.edu/papers/2000/sun-2000-pdrs-f00d.pdf"},"_projectIds":[],"grcSelected":false,"status":"published","visibility":"public","projectIds":[],"memberAuthors":["sun-xian-he"]}')}}]);